mapper.select:
SELECT ,
       COALESCE(tt.title, tm.title, t.template_title) AS display_title
  FROM task t
  LEFT JOIN template tm ON tm.id = t.template_id
  LEFT JOIN template_translation tt
    ON tt.template_id = t.template_id AND tt.locale = #{locale}
 WHERE t.id = #{id}
   AND t.user_id = #{userId}

SELECT 
  FROM task t
 WHERE t.id = #{id}

SELECT 
  FROM task t
 WHERE t.user_id = #{userId}
   AND t.client_request_id = #{clientRequestId}

